def squash(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""
    out = []
    i = 0
    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1
        length = j - i
        esc = "\\" + c if c == "\\" or "0" <= c <= "9" else c
        if length >= 3:
            out.append(str(length))
            out.append(esc)
        else:
            out.append(esc * length)
        i = j
    return "".join(out)
